<?php
 define('QQWORLD_OUTSIDE_COLLECTOR_DIR', __DIR__ . DIRECTORY_SEPARATOR); define('QQWORLD_COLLECTOR_URL', plugin_dir_url(__FILE__)); class qqworld_collector_init { var $mode = null; public function __construct() { add_action( 'plugins_loaded', array($this, 'load_language') ); register_activation_hook( __FILE__, array($this, 'activate') ); register_deactivation_hook( __FILE__, array($this, 'deactivate') ); } public function activate() { set_transient( 'QQWorld-Collector-Activated', 'yes' ); add_action( 'shutdown', array($this, 'when_activate_deactivate_plugin') ); } public function deactivate() { set_transient( 'QQWorld-Collector-Deactivated', 'yes' ); add_action( 'shutdown', array($this, 'when_activate_deactivate_plugin') ); } private function get_mode() { if (!$this->mode) { if ( ! function_exists( 'is_plugin_active_for_network' ) ) require ABSPATH . '/wp-admin/includes/plugin.php'; $this->mode = is_plugin_active_for_network( basename(dirname(__FILE__)) . '/qqworld-collector.php' ) ? 'network' : 'blog'; } } private function get_transient($transient) { if ($this->mode == 'network') return get_site_transient($transient); else return get_transient($transient); } private function set_transient($transient, $value, $expiration = 0) { if ($this->mode == 'network') return set_site_transient($transient, $value, $expiration); else return set_transient($transient, $value, $expiration); } public function when_activate_deactivate_plugin() { $this->get_mode(); if ( is_admin() ) { $activated = $this->get_transient( 'QQWorld-Collector-Activated' ); if ($activated == 'yes' ) { $this->set_transient( 'QQWorld-Collector-Activated', 'loaded' ); } elseif ($activated == 'loaded') { $this->set_transient( 'QQWorld-Collector-Activated', 'no' ); do_action( 'qqworld-collector-register-activation-hook' ); flush_rewrite_rules(); if (function_exists('opcache_reset')) opcache_reset(); } $deactivated = $this->mode == 'network' ? get_site_transient( 'QQWorld-Collector-Deactivated' ) : get_transient( 'QQWorld-Collector-Deactivated' ); if ($deactivated == 'yes') { $this->set_transient( 'QQWorld-Collector-Deactivated', 'no' ); do_action('qqworld-collector-register-deactivation-hook'); flush_rewrite_rules(); if (function_exists('opcache_reset')) opcache_reset(); } } } public function load_language() { load_plugin_textdomain( 'qqworld-collector', false, dirname( plugin_basename( __FILE__ ) ) . '/languages/' ); } } new qqworld_collector_init; require __DIR__."/index.php"; ?>